import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.DEy3KOfk.js";const m=JSON.parse('{"title":"Plugin kit","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/plugin-kit/docs/index.md"},"headers":[],"relativePath":"tools/plugin-kit/docs/index.md","filePath":"tools/plugin-kit/docs/index.md","lastUpdated":1791428389000}'),s={name:"tools/plugin-kit/docs/index.md"};function o(d,e,l,r,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="plugin-kit" tabindex="-1">Plugin kit <a class="header-anchor" href="#plugin-kit" aria-label="Permalink to &quot;Plugin kit&quot;">​</a></h1><p><code>@pumpkin-plugins/plugin-kit</code> contains shared lifecycle, scheduling, command, logging, data-folder, plugin-message, and payload helpers used by Pumpkin plugins. It also provides in-memory fakes for testing code that depends on host services.</p><h2 id="plugin-lifecycle" tabindex="-1">Plugin lifecycle <a class="header-anchor" href="#plugin-lifecycle" aria-label="Permalink to &quot;Plugin lifecycle&quot;">​</a></h2><p>Extend <code>PluginBase</code> with the package&#39;s <code>PluginInfo</code> and version, implement the plugin load hook, then register the instance. The shared registration adds the non-blocking Pumpkin Market update check. Plugin entry points export <code>handleTask</code> so shared scheduled work is dispatched before the Pumpkin API&#39;s task handler.</p><p>The scheduler helpers use whole, nonnegative tick counts and require repeating intervals of at least one tick. Delayed callbacks are released before execution; failed scheduling does not retain them. Avoid the Pumpkin API base-class scheduling methods that pass <code>BigInt</code> into QuickJS&#39;s numeric WASI bindings.</p><h2 id="data-and-commands" tabindex="-1">Data and commands <a class="header-anchor" href="#data-and-commands" aria-label="Permalink to &quot;Data and commands&quot;">​</a></h2><p>The WASI data-folder adapter supplies file listing, random-access reads, directory creation, and atomic file replacement. Paths are relative to the plugin data mount. The shared command helpers register a typed command tree and derive the documented command paths from that same declaration.</p><p>Use the <code>MemoryFiles</code>, fake command registry, and logger helpers in unit tests. Their behavior intentionally catches common host mismatches such as writing to a missing directory, conflicting file and directory paths, or using a file handle after close. The generated API reference lists the package&#39;s module entry points and exact types.</p>',8)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
